SCHEMA_SQL = ("CREATE FUNCTION public.m3_lock_variant_audience_target(t uuid,c uuid,sid uuid,expected_owner uuid)\nRETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER\nSET search_path=pg_catalog,public,pg_temp AS $$\nDECLARE model_id uuid; actual_owner uuid;\nBEGIN\n IF category_access(t,c) IS DISTINCT FROM true OR scope_actor() IS DISTINCT FROM scope_requester()\n  OR NOT EXISTS(SELECT 1 FROM principals person WHERE person.tenant_id=t AND person.id=scope_actor()\n   AND person.active AND person.kind='human') THEN RETURN false; END IF;\n SELECT variant.product_id,variant.owner_id INTO model_id,actual_owner FROM product_variants variant\n  WHERE variant.tenant_id=t AND variant.category_id=c AND variant.id=sid;\n IF NOT FOUND OR actual_owner IS DISTINCT FROM expected_owner OR\n  ((actual_owner=scope_requester() AND category_access(t,c,true))\n    OR m3_result_access(t,c,'product_variants',sid)) IS DISTINCT FROM true THEN RETURN false; END IF;\n -- Preserve the original Product-before-target lock order and its audience boundary.\n PERFORM 1 FROM products model WHERE model.tenant_id=t AND model.category_id=c AND model.id=model_id\n  AND source_object_audience(t,c,'products',model.id,model.owner_id,model.visibility) FOR UPDATE;\n IF NOT FOUND THEN RETURN false; END IF;\n PERFORM 1 FROM product_variants variant\n  WHERE variant.tenant_id=t AND variant.category_id=c AND variant.id=sid\n   AND variant.product_id=model_id AND variant.owner_id=expected_owner\n   AND ((variant.owner_id=scope_requester() AND category_access(t,c,true))\n    OR m3_result_access(t,c,'product_variants',variant.id)) FOR UPDATE;\n RETURN FOUND;\nEND $$", 'REVOKE ALL ON FUNCTION public.m3_lock_variant_audience_target(uuid,uuid,uuid,uuid) FROM PUBLIC,pdos_agent,pdos_next_app,pdos_next_auth,pdos_next_dispatch', 'GRANT EXECUTE ON FUNCTION public.m3_lock_variant_audience_target(uuid,uuid,uuid,uuid) TO pdos_next_app', 'CREATE OR REPLACE FUNCTION public.protect_object_audience_target()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO \'pg_catalog\', \'public\', \'pg_temp\'\nAS $function$\nDECLARE value jsonb; typ text; own_col text; model_col text;\n t uuid; c uuid; sid uuid; expected_owner uuid; actual_owner uuid; model uuid;\n owners jsonb=\'{"action_receipts": "requester_id", "actual_configurations": "owner_id", "artifact_versions": "owner_id", "bom_revisions": "owner_id", "build_authorization_decisions": "owner_id", "build_execution_assessments": "owner_id", "build_lots": "owner_id", "build_operational_facts": "owner_id", "build_readiness": "owner_id", "build_starts": "owner_id", "builds": "owner_id", "capa_current_observations": "owner_id", "capa_current_verification_rules": "owner_id", "capa_named_verification_reviews": "owner_id", "capa_observation_facts": "owner_id", "capa_remediation_links": "owner_id", "capa_verification_evidence": "owner_id", "capa_verification_rule_facts": "owner_id", "change_approval_records": "owner_id", "change_graph_captures": "owner_id", "change_implementation_captures": "owner_id", "change_implementation_records": "owner_id", "change_order_records": "owner_id", "change_request_versions": "owner_id", "controlled_change_coverage_currents": "owner_id", "controlled_change_coverage_facts": "owner_id", "controlled_change_policy_currents": "owner_id", "controlled_change_policy_facts": "owner_id", "controlled_change_selection_currents": "owner_id", "controlled_change_selection_facts": "owner_id", "cost_estimates": "owner_id", "cost_input_snapshots": "owner_id", "cost_source_captures": "owner_id", "definition_revisions": "owner_id", "engineering_configurations": "owner_id", "manufacturing_preparation_currents": "owner_id", "manufacturing_preparation_versions": "owner_id", "measurement_import_captures": "owner_id", "parts": "owner_id", "plan_proposals": "owner_id", "plan_revisions": "owner_id", "process_revisions": "owner_id", "product_variants": "owner_id", "products": "owner_id", "professional_authority_facts": "owner_id", "projects": "owner_id", "quality_issue_versions": "owner_id", "quality_policy_facts": "owner_id", "sample_allocations": "owner_id", "sample_readiness_facts": "owner_id", "sample_run_usages": "owner_id", "sample_units": "owner_id", "supply_kit_projections": "owner_id", "supply_snapshots": "owner_id", "supply_source_captures": "owner_id", "test_measurements": "owner_id", "test_resource_facts": "owner_id", "test_resource_reservations": "owner_id", "test_result_actions": "owner_id", "test_result_projections": "owner_id", "uploaded_originals": "owner_id", "variant_revisions": "owner_id", "verification_actual_method_applicabilities": "owner_id", "verification_actual_method_batches": "owner_id", "verification_formal_requests": "owner_id", "verification_handoff_facts": "owner_id", "verification_launch_facts": "owner_id", "verification_method_applicabilities": "owner_id", "verification_preparations": "owner_id", "verification_run_identities": "owner_id", "verification_run_versions": "owner_id", "verification_window_proposals": "owner_id", "proposals": "owner_id", "claims": "human_owner_id"}\'::jsonb;\nBEGIN\n IF TG_OP=\'DELETE\' THEN value=to_jsonb(OLD); ELSE value=to_jsonb(NEW); END IF;\n IF TG_OP=\'UPDATE\' AND\n   ROW(NEW.tenant_id,NEW.category_id,NEW.object_type,NEW.subject_id,NEW.owner_id)\n   IS DISTINCT FROM ROW(OLD.tenant_id,OLD.category_id,OLD.object_type,OLD.subject_id,OLD.owner_id)\n THEN RAISE EXCEPTION \'audience identity cannot be reassigned\' USING ERRCODE=\'23514\'; END IF;\n typ=value->>\'object_type\'; own_col=owners->>typ;\n t=(value->>\'tenant_id\')::uuid; c=(value->>\'category_id\')::uuid;\n sid=(value->>\'subject_id\')::uuid; expected_owner=(value->>\'owner_id\')::uuid;\n IF own_col IS NULL THEN\n  RAISE EXCEPTION \'audience target unavailable\' USING ERRCODE=\'23514\';\n END IF;\n IF typ=\'product_variants\' THEN\n  IF m3_lock_variant_audience_target(t,c,sid,expected_owner) IS DISTINCT FROM true THEN\n   RAISE EXCEPTION \'audience target unavailable\' USING ERRCODE=\'23514\';\n  END IF;\n  IF TG_OP=\'DELETE\' THEN RETURN OLD; ELSE RETURN NEW; END IF;\n END IF;\n model_col=CASE WHEN typ=\'products\' THEN \'id\' WHEN typ=\'proposals\' THEN \'baseline_product_id\' ELSE \'product_id\' END;\n EXECUTE format(\'SELECT %I,%I FROM public.%I WHERE tenant_id=$1 AND category_id=$2 AND id=$3\',\n                own_col,model_col,typ) INTO actual_owner,model USING t,c,sid;\n IF actual_owner IS DISTINCT FROM expected_owner THEN\n  RAISE EXCEPTION \'audience target unavailable\' USING ERRCODE=\'23514\';\n END IF;\n IF model IS NOT NULL THEN\n  PERFORM 1 FROM products WHERE tenant_id=t AND category_id=c AND id=model FOR UPDATE;\n  IF NOT FOUND THEN\n   RAISE EXCEPTION \'audience model unavailable\' USING ERRCODE=\'23514\';\n  END IF;\n END IF;\n EXECUTE format(\'SELECT %I FROM public.%I\n  WHERE tenant_id=$1 AND category_id=$2 AND id=$3 FOR UPDATE\',\n                own_col,typ) INTO actual_owner USING t,c,sid;\n IF actual_owner IS DISTINCT FROM expected_owner THEN\n  RAISE EXCEPTION \'audience target unavailable\' USING ERRCODE=\'23514\';\n END IF;\n IF TG_OP=\'DELETE\' THEN RETURN OLD; ELSE RETURN NEW; END IF;\nEND $function$\n')

